function validate([forward, backward, queries]) {
  const n = forward.length;
  if (n < 2 || n > 100000) return 'There are 2 to 10^5 houses.';
  if (backward.length !== n) return 'forward and backward must have the same length.';
  if (forward.some(v => v < 1 || v > 100000) || backward.some(v => v < 1 || v > 100000)) return 'Every step takes between 1 and 10^5 seconds.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 houses.';
  if (queries.some(house => house < 0 || house >= n)) return 'Each query is a house number from 0 to n - 1.';
  if (queries[0] === 0) return 'The first house to visit cannot be house 0, where you start.';
  if (queries.some((house, i) => i > 0 && house === queries[i - 1])) return 'Two consecutive queries must name different houses.';
  return null;
}

