function minTotalTime(forward, backward, queries) {
  const n = forward.length;
  // ahead[i]: forward[0] + ... + forward[i - 1], the clockwise time from house 0 to house i.
  const ahead = new Array(n + 1).fill(0);
  // behind[i]: backward[0] + ... + backward[i - 1].
  const behind = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    ahead[i + 1] = ahead[i] + forward[i];
    behind[i + 1] = behind[i] + backward[i];
  }
  let current = 0;
  let total = 0;
  for (const target of queries) {
    // Clockwise steps leave houses current, current + 1, ..., target - 1.
    let clockwise = ahead[target] - ahead[current];
    if (target < current) {
      clockwise += ahead[n];
    }
    // Counterclockwise steps leave houses current, current - 1, ..., target + 1.
    let counterclockwise = behind[current + 1] - behind[target + 1];
    if (target > current) {
      counterclockwise += behind[n];
    }
    total += Math.min(clockwise, counterclockwise);
    current = target;
  }
  return total;
}

