function minTotalTime(forward, backward, queries) {
  // Walk each leg step by step in both directions and keep the faster one.
  const n = forward.length;
  let at = 0;
  let total = 0;
  for (const target of queries) {
    let clockwise = 0;
    for (let house = at; house !== target; house = (house + 1) % n) clockwise += forward[house];
    let counterclockwise = 0;
    for (let house = at; house !== target; house = (house - 1 + n) % n) counterclockwise += backward[house];
    total += Math.min(clockwise, counterclockwise);
    at = target;
  }
  return total;
}

