function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  const top = large || rand() < 0.3 ? 100000 : 9;
  const pick = () => 1 + Math.floor(rand() * top);
  const forward = Array.from({ length: n }, pick);
  const backward = Array.from({ length: n }, pick);
  // Sometimes one direction is much cheaper everywhere, so long one-way walks win.
  const skew = rand();
  if (skew < 0.2) forward.forEach((_, i) => { forward[i] = 1 + Math.floor(forward[i] / 50); });
  else if (skew < 0.4) backward.forEach((_, i) => { backward[i] = 1 + Math.floor(backward[i] / 50); });
  const count = large ? 2000 : 1 + Math.floor(rand() * 8);
  const queries = [];
  let previous = 0;
  for (let i = 0; i < count; i++) {
    // Pick any house except the previous one (house 0 before the first visit).
    let next = Math.floor(rand() * (n - 1));
    if (next >= previous) next++;
    queries.push(next);
    previous = next;
  }
  return [forward, backward, queries];
}
